import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Long, Long> memoMap = new HashMap<>();

    public static long recursiveFunction(long n) {
        if (memoMap.containsKey(n)) {
            return memoMap.get(n);
        }
        if (n <= 11) {
            long result = Math.min(n, 2 + (11 - n));
            memoMap.put(n, result);
            return result;
        }
        long base = 1;
        int count = 1;
        while (base <= n) {
            base = base * 10 + 1;
            count++;
        }
        long limit = base / 10;
        long option1 = 0, option2 = 0;
        if (base > 2 * n) {
            long times = n / limit;
            long rem = n % limit;
            option1 = recursiveFunction(base - n) + count;
            option2 = times * (count - 1) + recursiveFunction(rem);
        } else {
            long times = n / limit;
            long rem = n % limit;
            option1 = recursiveFunction(base - n) + count;
            option2 = times * (count - 1) + recursiveFunction(rem);
        }
        long result = Math.min(option1, option2);
        memoMap.put(n, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long number = scanner.nextLong();
        System.out.println(recursiveFunction(number));
        scanner.close();
    }
}
